document.querySelectorAll(".wp-block-white-oaks-click-to-load-map").forEach(e=>{e.addEventListener("click",s=>{if(s.target.closest("[data-map-directions]")||s.button!==0||s.altKey||s.ctrlKey||s.metaKey||s.shiftKey||(s.preventDefault(),e.classList.contains("is-loading")||e.classList.contains("is-loaded")))return;e.classList.add("is-loading"),e.setAttribute("aria-busy","true");const t=document.createElement("iframe"),r=new URL("https://www.google.com/maps");r.searchParams.set("q",e.dataset.mapQuery||""),r.searchParams.set("output","embed"),t.src=r.toString(),t.title=`Interactive map showing ${e.dataset.mapQuery||"this location"}`,t.loading="eager",t.referrerPolicy="no-referrer-when-downgrade",t.allowFullscreen=!0,t.tabIndex=0,t.addEventListener("load",()=>{e.classList.remove("is-loading"),e.classList.add("is-loaded"),e.setAttribute("aria-busy","false"),t.focus({preventScroll:!0})},{once:!0}),e.append(t)})});
